class MockField(models.Field):
    def __init__(self):
        super().__init__()

    def deconstruct(self):
        return ("name", "django.db.models.CharField", [], {"max_length": 255})


class MockManager(models.manager.BaseManager):
    def deconstruct(self):
        return (False, "myapp.managers.MyManager", None, [], {})


class MockOperation:
    def deconstruct(self):
        return ("name", "path", [], {})


class MockPromise(Promise):
    def __str__(self):
        return "mock promise"


class TestBaseSerializer:
    def test_base_serializer_init(self):
        value = "test"
        serializer = BaseSerializer(value)
        assert serializer.value == value

    def test_base_serializer_serialize_not_implemented(self):
        serializer = BaseSerializer("test")
        try:
            serializer.serialize()
            assert False, "Should raise NotImplementedError"
        except NotImplementedError as e:
            assert "Subclasses of BaseSerializer must implement the serialize() method" in str(e)


class TestBaseSequenceSerializer:
    def test_base_sequence_serializer_format_not_implemented(self):
        serializer = BaseSequenceSerializer([1, 2, 3])
        try:
            serializer._format()
            assert False, "Should raise NotImplementedError"
        except NotImplementedError as e:
            assert "Subclasses of BaseSequenceSerializer must implement the _format() method" in str(e)

    def test_base_sequence_serializer_serialize(self):
        class TestSerializer(BaseSequenceSerializer):
            def _format(self):
                return "[%s]"

        serializer = TestSerializer([1, 2, 3])
        result, imports = serializer.serialize()
        assert result == "[1, 2, 3]"
        assert imports == set()


class TestBaseUnorderedSequenceSerializer:
    def test_base_unordered_sequence_serializer_init(self):
        class TestSerializer(BaseUnorderedSequenceSerializer):
            def _format(self):
                return "[%s]"

        # Should sort by repr
        serializer = TestSerializer([3, 1, 2])
        assert serializer.value == [1, 2, 3]


