class TestDateTimeSerializer:
    def test_datetime_serializer_serialize_date(self):
        date_obj = datetime.date(2023, 1, 1)
        serializer = DateTimeSerializer(date_obj)
        result, imports = serializer.serialize()
        assert result == "datetime.date(2023, 1, 1)"
        assert imports == {"import datetime"}

    def test_datetime_serializer_serialize_time(self):
        time_obj = datetime.time(12, 30, 0)
        serializer = DateTimeSerializer(time_obj)
        result, imports = serializer.serialize()
        assert result == "datetime.time(12, 30, 0)"
        assert imports == {"import datetime"}

    def test_datetime_serializer_serialize_timedelta(self):
        td = datetime.timedelta(days=1)
        serializer = DateTimeSerializer(td)
        result, imports = serializer.serialize()
        assert result == "datetime.timedelta(days=1)"
        assert imports == {"import datetime"}


class TestDatetimeDatetimeSerializer:
    def test_datetime_datetime_serializer_serialize_utc(self):
        dt = datetime.datetime(2023, 1, 1, tzinfo=datetime.timezone.utc)
        serializer = DatetimeDatetimeSerializer(dt)
        result, imports = serializer.serialize()
        assert result == repr(dt)
        assert imports == {"import datetime"}

    def test_datetime_datetime_serializer_serialize_non_utc(self):
        tz = datetime.timezone(datetime.timedelta(hours=5))
        dt = datetime.datetime(2023, 1, 1, tzinfo=tz)
        serializer = DatetimeDatetimeSerializer(dt)
        result, imports = serializer.serialize()
        # Should convert to UTC
        assert imports == {"import datetime"}


