class TestDeconstructableSerializer:
    def test_deconstructable_serializer_serialize(self):
        class MockDeconstructable:
            def deconstruct(self):
                return ("attr", "module.ClassName", [1, 2], {"key": "value"})

        serializer = DeconstructableSerializer(MockDeconstructable())
        result, imports = serializer.serialize()
        assert "module.ClassName(1, 2, key='value')" in result
        assert "import module" in imports

    def test_deconstructable_serializer_serialize_django_models(self):
        class MockDjangoDeconstructable:
            def deconstruct(self):
                return ("attr", "django.db.models.CharField", [], {"max_length": 255})

        serializer = DeconstructableSerializer(MockDjangoDeconstructable())
        result, imports = serializer.serialize()
        assert "models.CharField(max_length=255)" in result
        assert "from django.db import models" in imports


