class TestFunctionTypeSerializer:
    def test_function_type_serializer_serialize_method(self):
        def my_func():
            pass

        serializer = FunctionTypeSerializer(my_func)
        result, imports = serializer.serialize()
        assert "my_func" in result
        assert "import __main__" in imports or "import test_" in imports

    def test_function_type_serializer_serialize_lambda_error(self):
        lambda_func = lambda x: x
        serializer = FunctionTypeSerializer(lambda_func)
        try:
            serializer.serialize()
            assert False, "Should raise ValueError"
        except ValueError as e:
            assert "Cannot serialize function: lambda" in str(e)

    def test_function_type_serializer_serialize_no_module_error(self):
        def local_func():
            pass

        # Remove module attribute to simulate no module
        original_module = local_func.__module__
        local_func.__module__ = None
        try:
            serializer = FunctionTypeSerializer(local_func)
            serializer.serialize()
            assert False, "Should raise ValueError"
        except ValueError as e:
            assert "Cannot serialize function" in str(e)
        finally:
            local_func.__module__ = original_module


