class TestSerializerRegistry:
    def test_register_valid_serializer(self):
        class TestSerializer(BaseSerializer):
            def serialize(self):
                return "test", set()

        Serializer.register(int, TestSerializer)
        assert int in Serializer._registry
        del Serializer._registry[int]

    def test_register_invalid_serializer(self):
        class InvalidSerializer:
            pass

        try:
            Serializer.register(int, InvalidSerializer)
            assert False, "Should raise ValueError"
        except ValueError as e:
            assert "must inherit from 'BaseSerializer'" in str(e)

    def test_unregister(self):
        Serializer.unregister(list)
        assert list not in Serializer._registry
        # Re-register for other tests
        Serializer.register(list, SequenceSerializer)


