import threading
import time
from pathlib import Path
from unittest import mock
from unittest.mock import MagicMock, patch

from django.utils import autoreload
from django.utils.autoreload import WatchmanUnavailable


class TestCheckErrors:
    def test_check_errors_decorator_success(self):
        @autoreload.check_errors
        def success_fn():
            return "success"

        result = success_fn()
        assert result == "success"

    def test_check_errors_decorator_raises_exception(self):
        @autoreload.check_errors
        def failing_fn():
            raise ValueError("test error")

        try:
            failing_fn()
        except ValueError as e:
            assert str(e) == "test error"

    def test_check_errors_decorator_sets_exception(self):
        @autoreload.check_errors
        def failing_fn():
            raise RuntimeError("runtime error")

        try:
            failing_fn()
        except RuntimeError:
            pass

        assert autoreload._exception is not None


class TestRaiseLastException:
    def test_raise_last_exception_no_exception(self):
        autoreload._exception = None
        autoreload.raise_last_exception()  # Should not raise

    def test_raise_last_exception_with_exception(self):
        autoreload._exception = (ValueError, ValueError("test"), None)
        try:
            autoreload.raise_last_exception()
        except ValueError as e:
            assert str(e) == "test"


class TestEnsureEchoOn:
    @mock.patch('django.utils.autoreload.termios', None)
    def test_ensure_echo_on_no_termios(self):
        autoreload.ensure_echo_on()  # Should not raise

    @mock.patch('django.utils.autoreload.termios')
    @mock.patch.object(sys.stdin, 'isatty', return_value=False)
    def test_ensure_echo_on_not_tty(self, mock_isatty, mock_termios):
        autoreload.ensure_echo_on()  # Should not raise

    @mock.patch('django.utils.autoreload.termios')
    @mock.patch.object(sys.stdin, 'isatty', return_value=True)
    def test_ensure_echo_on_echo_already_on(self, mock_isatty, mock_termios):
        mock_attr_list = [0, 0, 0, 0]
        mock_attr_list[3] = 1  # ECHO bit set
        mock_termios.tcgetattr.return_value = mock_attr_list
        mock_termios.ECHO = 1

        autoreload.ensure_echo_on()
        mock_termios.tcsetattr.assert_not_called()


