        serializer = serializer_factory(data)
        result, imports = serializer.serialize()
        assert "list" in result
        assert "dict" in result

    def test_unicode_string(self):
        serializer = serializer_factory("unicode \u00e9")
        result, imports = serializer.serialize()
        assert "unicode" in result

    def test_special_characters_in_string(self):
        serializer = serializer_factory("special\n\t\r")
        result, imports = serializer.serialize()
        assert "special" in result

    def test_zero_values(self):
        serializer = serializer_factory(0)
        result, imports = serializer.serialize()
        assert result == "0"

    def test_negative_numbers(self):
        serializer = serializer_factory(-42)
        result, imports = serializer.serialize()
        assert result == "-42"

    def test_large_number(self):
        serializer = serializer_factory(10**100)
        result, imports = serializer.serialize()
        assert "10" in result

    def test_complex_number_not_supported(self):
        with self.assertRaises(ValueError):
            serializer_factory(complex(1, 2))

