class MethodDecoratorTests(unittest.TestCase):
    def test_method_decorator_basic_function(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        @method_decorator(my_decorator)
        def my_view(request):
            return "view"

        result = my_view(None)
        self.assertEqual(result, "view_decorated")

    def test_method_decorator_on_class_method(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyView:
            @method_decorator(my_decorator)
            def my_method(self):
                return "method"

        view = MyView()
        result = view.my_method()
        self.assertEqual(result, "method_decorated")

    def test_method_decorator_preserves_name(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyView:
            @method_decorator(my_decorator)
            def my_method(self):
                return "method"

        self.assertEqual(MyView.my_method.__name__, "my_method")

    def test_method_decorator_multiple_decorators(self):
        def decorator1(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_1"
            return wrapper

        def decorator2(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_2"
            return wrapper

        class MyView:
            @method_decorator([decorator1, decorator2])
            def my_method(self):
                return "method"

        view = MyView()
        result = view.my_method()
        self.assertEqual(result, "method_1_2")

    def test_method_decorator_value_error_missing_name(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            pass

        with self.assertRaises(ValueError):
            @method_decorator(my_decorator, name='nonexistent')
            class MyClass:
                pass

    def test_method_decorator_type_error_non_callable(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            non_callable = 42

        with self.assertRaises(TypeError):
            @method_decorator(my_decorator, name='non_callable')
            class MyClass:
                pass

    def test_method_decorator_returns_class(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            @method_decorator(my_decorator)
            def my_method(self):
                return "method"

        self.assertIsInstance(MyClass, type)


