class MethodDecoratorEdgeCasesTests(unittest.TestCase):
    def test_method_decorator_with_args_kwargs(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + f"_args_{len(args)}_kwargs_{len(kwargs)}"
            return wrapper

        class MyView:
            @method_decorator(my_decorator)
            def my_method(self, arg1, arg2=None):
                return "method"

        view = MyView()
        result = view.my_method("a", b="b")
        self.assertIn("_args_", result)

    def test_method_decorator_preserves_docstring(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyView:
            @method_decorator(my_decorator)
            def my_method(self):
                """This is a docstring"""
                return "method"

        self.assertEqual(MyView.my_method.__doc__, "This is a docstring")

    def test_method_decorator_with_partial(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyView:
            @method_decorator(my_decorator)
            def my_method(self):
                return "method"

        view = MyView()
        bound_method = view.my_method
        result = bound_method()
        self.assertEqual(result, "method_decorated")


