class DecoratorFromMiddlewareEdgeCasesTests(unittest.TestCase):
    def test_make_middleware_decorator_no_process_methods(self):
        class MinimalMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        decorator = make_middleware_decorator(MinimalMiddleware)
        decorated = decorator()(lambda request: "response")
        result = decorated(None)
        self.assertEqual(result, "response")

    def test_make_middleware_decorator_all_process_methods(self):
        class FullMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                return None

            def process_view(self, request, view_func, args, kwargs):
                return None

            def process_exception(self, request, exception):
                return None

            def process_template_response(self, request, response):
                return response

            def process_response(self, request, response):
                return response

        decorator = make_middleware_decorator(FullMiddleware)
        decorated = decorator()(lambda request: "response")
        result = decorated(None)
        self.assertEqual(result, "response")

    def test_make_middleware_decorator_exception_in_view(self):
        class ExceptionMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                return None

            def process_exception(self, request, exception):
                raise RuntimeError("middleware_exception")

        decorator = make_middleware_decorator(ExceptionMiddleware)
        decorated = decorator()(lambda request: (_ for _ in ()).throw(Exception("view_exception")))

        with self.assertRaises(RuntimeError) as context:
            decorated(None)
        self.assertEqual(str(context.exception), "middleware_exception")

