import os
import sys
import unittest
from unittest import mock

from django.core.management import CommandError
from django.test import TestCase


class ShellCommandTests(TestCase):
    """Tests for django.core.management.commands.shell.Command"""

    def setUp(self):
        from django.core.management.commands.shell import Command
        self.command = Command()

    def test_command_help_text(self):
        """Test command help text contains expected information"""
        self.assertIn("interactive interpreter", self.command.help)
        self.assertIn("IPython", self.command.help)
        self.assertIn("bpython", self.command.help)

    def test_requires_system_checks_disabled(self):
        """Test that system checks are disabled for this command"""
        self.assertFalse(self.command.requires_system_checks)

    def test_shells_attribute(self):
        """Test available shells list"""
        self.assertEqual(self.command.shells, ['ipython', 'bpython', 'python'])

    def test_add_arguments_no_startup(self):
        """Test no-startup argument is added"""
        from argparse import ArgumentParser
        parser = ArgumentParser()
        self.command.add_arguments(parser)
        actions = {action.dest: action for action in parser._actions}
        self.assertIn('no_startup', actions)
        self.assertTrue(actions['no_startup'].store_true)

    def test_add_arguments_interface(self):
        """Test interface argument is added with choices"""
        from argparse import ArgumentParser
        parser = ArgumentParser()
        self.command.add_arguments(parser)
        actions = {action.dest: action for action in parser._actions}
        self.assertIn('interface', actions)
        self.assertEqual(actions['interface'].choices, self.command.shells)

    def test_add_arguments_command(self):
        """Test command argument is added"""
        from argparse import ArgumentParser
        parser = ArgumentParser()
        self.command.add_arguments(parser)
        actions = {action.dest: action for action in parser._actions}
        self.assertIn('command', actions)

    @mock.patch('django.core.management.commands.shell.Command.ipython')
    def test_handle_with_interface_option(self, mock_ipython):
        """Test handle method with specific interface option"""
        options = {'interface': 'ipython', 'command': None}
        self.command.handle(**options)
        mock_ipython.assert_called_once_with(options)

    @mock.patch('django.core.management.commands.shell.Command.python')
    def test_handle_falls_back_to_python_when_ipython_not_available(self, mock_python):
        """Test fallback to plain Python when IPython unavailable"""
        options = {'interface': None, 'command': None}

        with mock.patch.object(self.command, 'ipython', side_effect=ImportError()):
            with mock.patch.object(self.command, 'bpython', side_effect=ImportError()):
                self.command.handle(**options)
                mock_python.assert_called_once_with(options)

    @mock.patch('django.core.management.commands.shell.Command.bpython')
    def test_handle_falls_back_to_python_when_bpython_not_available(self, mock_bpython):
        """Test fallback to plain Python when bpython unavailable"""
        options = {'interface': None, 'command': None}

        with mock.patch.object(self.command, 'ipython', side_effect=ImportError()):
            with mock.patch.object(self.command, 'bpython', side_effect=ImportError()):
                self.command.handle(**options)

    @mock.patch('django.core.management.commands.shell.Command.python')
    def test_handle_specific_shell_requested(self, mock_python):
        """Test specific shell is used when requested"""
        options = {'interface': 'python', 'command': None}
        self.command.handle(**options)
        mock_python.assert_called_once_with(options)

    @mock.patch('builtins.exec')
    def test_handle_executes_command_option(self, mock_exec):
        """Test command option executes code and exits"""
        options = {'interface': None, 'command': 'print("test")'}
        self.command.handle(**options)
        mock_exec.assert_called_once_with('print("test")', globals())

    @mock.patch('sys.stdin.isatty')
    @mock.patch('select.select')
    def test_handle_executes_stdin_when_not_tty(self, mock_select, mock_isatty):
        """Test that stdin is executed when not a TTY and has content"""
        mock_isatty.return_value = False
        mock_select.return_value = ([sys.stdin], [], [])

        with mock.patch('sys.stdin.read', return_value='print("hello")'):
            with mock.patch('builtins.exec') as mock_exec:
                self.command.handle(interface=None, command=None)
                mock_exec.assert_called_once()

    @mock.patch('sys.stdin.isatty')
    @mock.patch('select.select')
    def test_handle_skips_stdin_when_empty(self, mock_select, mock_isatty):
        """Test that empty stdin doesn't trigger execution"""
        mock_isatty.return_value = False
        mock_select.return_value = ([], [], [])

        with mock.patch('sys.stdin.read', return_value=''):
            with mock.patch('builtins.exec') as mock_exec:
                self.command.handle(interface=None, command=None)
                mock_exec.assert_not_called()

    @mock.patch('sys.platform', 'win32')
    def test_handle_skips_stdin_on_windows(self, mock_platform):
        """Test that stdin execution is skipped on Windows"""
        with mock.patch('sys.stdin.isatty', return_value=False):
            with mock.patch('builtins.exec') as mock_exec:
                self.command.handle(interface=None, command=None)
                mock_exec.assert_not_called()

