class TestOptionBase:
    """Tests for base Option classes."""

    def test_option_default(self):
        assert Option.default() is None

    def test_flag_is_flag(self):
        assert Flag.is_Flag is True

    def test_boolean_option_preprocess_true(self):
        result = BooleanOption.preprocess(True)
        assert result is True

    def test_boolean_option_preprocess_false(self):
        result = BooleanOption.preprocess(False)
        assert result is False

    def test_boolean_option_preprocess_invalid(self):
        try:
            BooleanOption.preprocess("invalid")
            assert False, "Should raise OptionError"
        except OptionError:
            pass


