        opts = Options(None, {'domain': 'ZZ'})
        assert opts['gens'] == ()

    def test_options_strict_mode(self):
        try:
            Options((x,), {'auto': True}, strict=True)
            assert False, "Should raise OptionError"
        except OptionError:
            pass


