        class BadRepr:
            def __repr__(self):
                raise KeyboardInterrupt()

        with pytest.raises(KeyboardInterrupt):
            _try_repr_or_str(BadRepr())

    def test_repr_raises_system_exit(self):
        class BadRepr:
            def __repr__(self):
                raise SystemExit()

        with pytest.raises(SystemExit):
            _try_repr_or_str(BadRepr())

    def test_repr_raises_other_exception(self):
        class BadRepr:
            def __repr__(self):
                raise ValueError("bad repr")

        result = _try_repr_or_str(BadRepr())
        assert "BadRepr" in result
        assert "bad repr" in result or "ValueError" in result


