import unittest
from unittest import mock
from django.db.migrations.autodetector import MigrationAutodetector
from django.db.migrations.questioner import MigrationQuestioner
from django.db.migrations.state import ProjectState, ModelState
from django.db.migrations.operations.models import AlterModelOptions
from django.db.models import Model as DjangoModel
from django.db import models


class MockField(models.Field):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)

    def deconstruct(self):
        return ('django.db.models.fields.CharField', [], {'max_length': 100})


class MockRemoteField:
    def __init__(self, model=None, through=None):
        self.model = model
        self.through = through


class MockMeta:
    def __init__(self, managed=True, proxy=False, auto_created=False):
        self.managed = managed
        self.proxy = proxy
        self.auto_created = auto_created

    def get_field(self, name):
        return MockField()


class MockModel:
    def __init__(self, app_label='test_app', model_name='TestModel'):
        self._meta = MockMeta()
        self._meta.app_label = app_label
        self._meta.model_name = model_name.lower()
        self.__bases__ = []
        self.name = model_name

    @property
    def _meta(self):
        return self._meta


class MockAppState:
    def __init__(self, models_dict=None):
        self.models_dict = models_dict or {}

    def get_model(self, app_label, model_name):
        key = (app_label, model_name)
        if key in self.models_dict:
            return self.models_dict[key]
        raise LookupError(f"Model {key} not found")


class MockProjectState:
    def __init__(self, models=None, real_apps=None):
        self.models = models or {}
        self.real_apps = real_apps or set()
        self.concrete_apps = MockAppState(self.models)
        self.apps = MockAppState(self.models)


class MockMigration:
    def __init__(self, name, app_label):
        self.name = name
        self.app_label = app_label
        self.dependencies = []
        self.operations = []
        self.initial = False


class MockGraph:
    def leaf_nodes(self, app_label):
        return [(app_label, "0001_initial")]


class MockOperation:
    _auto_deps = []

    def __init__(self, name_lower=""):
        self.name_lower = name_lower


class TestMigrationAutodetector(unittest.TestCase):

    def setUp(self):
        self.from_state = MockProjectState()
        self.to_state = MockProjectState()
        self.questioner = MigrationQuestioner()
        self.detector = MigrationAutodetector(self.from_state, self.to_state, self.questioner)

    def test_init(self):
        """Test detector initialization"""
        self.assertEqual(self.detector.from_state, self.from_state)
        self.assertEqual(self.detector.to_state, self.to_state)
