    NeighborsBase,
    KNeighborsMixin,
    RadiusNeighborsMixin,
    SupervisedFloatMixin,
    SupervisedIntegerMixin,
    UnsupervisedMixin,
    _check_weights,
    _get_weights,
    VALID_METRICS,
    VALID_METRICS_SPARSE,
)
from sklearn.neighbors import BallTree, KDTree
from sklearn.exceptions import NotFittedError
from sklearn.metrics.pairwise import PAIRWISE_DISTANCE_FUNCTIONS


class TestCheckWeights:
    """Tests for _check_weights function"""

    def test_check_weights_uniform(self):
        assert _check_weights('uniform') == 'uniform'

    def test_check_weights_distance(self):
        assert _check_weights('distance') == 'distance'

    def test_check_weights_none(self):
        assert _check_weights(None) is None

    def test_check_weights_callable(self):
        def my_weights(x):
            return x
        assert callable(_check_weights(my_weights))

    def test_check_weights_invalid(self):
        with pytest.raises(ValueError, match="weights not recognized"):
            _check_weights('invalid')


class TestGetWeights:
    """Tests for _get_weights function"""

    def test_get_weights_uniform(self):
        dist = np.array([[1., 2., 3.]])
        result = _get_weights(dist, 'uniform')
        assert result is None

    def test_get_weights_none(self):
        dist = np.array([[1., 2., 3.]])
        result = _get_weights(dist, None)
        assert result is None

    def test_get_weights_distance(self):
        dist = np.array([[1., 2., 3.]])
        result = _get_weights(dist, 'distance')
        expected = 1. / dist
        np.testing.assert_array_almost_equal(result, expected)

    def test_get_weights_callable(self):
        dist = np.array([[1., 2., 3.]])
        def my_weights(d):
            return d * 2
        result = _get_weights(dist, my_weights)
        expected = dist * 2
        np.testing.assert_array_almost_equal(result, expected)

    def test_get_weights_distance_zero_handling(self):
        dist = np.array([[0., 2., 3.]])
        result = _get_weights(dist, 'distance')
        assert result[0, 0] == 1.0

    def test_get_weights_distance_invalid(self):
        dist = np.array([[1., 2., 3.]])
        with pytest.raises(ValueError, match="weights not recognized"):
            _get_weights(dist, 'invalid')


class TestNeighborsBaseInit:
    """Tests for NeighborsBase initialization"""

    def test_init_default_params(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        nn = TestNeighbors()
        assert nn.n_neighbors is None
        assert nn.radius is None
        assert nn.algorithm == 'auto'
        assert nn.leaf_size == 30
        assert nn.metric == 'minkowski'
        assert nn.p == 2
        assert nn.n_jobs == 1

    def test_init_custom_params(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        nn = TestNeighbors(
            n_neighbors=5,
            radius=1.0,
            algorithm='ball_tree',
            leaf_size=20,
            metric='euclidean',
            p=3,
            n_jobs=2
        )
        assert nn.n_neighbors == 5
        assert nn.radius == 1.0
        assert nn.algorithm == 'ball_tree'
        assert nn.leaf_size == 20
        assert nn.metric == 'euclidean'
        assert nn.p == 3
        assert nn.n_jobs == 2

    def test_init_invalid_algorithm(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        with pytest.raises(ValueError, match="unrecognized algorithm"):
            TestNeighbors(algorithm='invalid')

    def test_init_callable_metric_kd_tree(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        def custom_metric(x, y):
            return np.sum(np.abs(x - y))

        with pytest.raises(ValueError, match="kd_tree algorithm does not support callable metric"):
            TestNeighbors(algorithm='kd_tree', metric=custom_metric)

    def test_init_minkowski_p_less_than_one(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        with pytest.raises(ValueError, match="p must be greater than one"):
            TestNeighbors(metric='minkowski', p=0.5)

    def test_init_metric_in_metric_params_warning(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        with pytest.warns(SyntaxWarning, match="Parameter p is found in metric_params"):
            TestNeighbors(metric='minkowski', metric_params={'p': 3})


