            nn._fit(X)

    def test_fit_sparse_brute_only(self):
        class TestNeighbors(NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                pass

        nn = TestNeighbors(algorithm='kd_tree')
        X = csr_matrix(np.array([[1., 2.], [3., 4.]]))
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            nn._fit(X)
