class TestKNeighborsMixin:
    """Tests for KNeighborsMixin methods"""

    def setup_method(self):
        self.X = np.array([[0., 0., 0.], [0., .5, 0.], [1., 1., .5]])
        self.nn = type('TestNN', (NeighborsBase, KNeighborsMixin), {
            '_fit': lambda self, X: self
        })()
        self.nn._fit_X = self.X
        self.nn._fit_method = 'brute'
        self.nn.effective_metric_ = 'euclidean'
        self.nn.effective_metric_params_ = {}
        self.nn.n_neighbors = 2
        self.nn.n_jobs = 1

    def test_kneighbors_not_fitted(self):
        nn = type('TestNN', (NeighborsBase, KNeighborsMixin), {
            '_fit': lambda self, X: self
        })()
        with pytest.raises(NotFittedError):
            nn.kneighbors()

    def test_kneighbors_no_query(self):
        nn = self.nn
        dist, ind = nn.kneighbors(return_distance=True)
        assert dist.shape == (3, 2)
        assert ind.shape == (3, 2)

    def test_kneighbors_with_query(self):
        nn = self.nn
        query = np.array([[1., 1., 1.]])
        dist, ind = nn.kneighbors(query, return_distance=True)
        assert dist.shape == (1, 2)
        assert ind.shape == (1, 2)

    def test_kneighbors_return_distance_false(self):
        nn = self.nn
        query = np.array([[1., 1., 1.]])
        ind = nn.kneighbors(query, return_distance=False)
        assert isinstance(ind, np.ndarray)
        assert ind.shape == (1, 2)

    def test_kneighbors_invalid_n_neighbors_zero(self):
        nn = self.nn
        with pytest.raises(ValueError, match="Expected n_neighbors > 0"):
            nn.kneighbors(n_neighbors=0)

    def test_kneighbors_n_neighbors_too_large(self):
        nn = self.nn
        query = np.array([[1., 1., 1.]])
        with pytest.raises(ValueError, match="Expected n_neighbors <= n_samples"):
            nn.kneighbors(query, n_neighbors=100)

    def test_kneighbors_graph_connectivity_mode(self):
        nn = self.nn
        graph = nn.kneighbors_graph(mode='connectivity')
        assert graph.shape == (3, 3)

    def test_kneighbors_graph_distance_mode(self):
        nn = self.nn
        graph = nn.kneighbors_graph(mode='distance')
        assert graph.shape == (3, 3)

    def test_kneighbors_graph_invalid_mode(self):
        nn = self.nn
        with pytest.raises(ValueError, match="Unsupported mode"):
            nn.kneighbors_graph(mode='invalid')


