class TestSupervisedMixins:
    """Tests for supervised mixins"""

    def test_supervised_float_mixin_fit(self):
        class TestNN(SupervisedFloatMixin, NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                return self

        X = np.array([[1., 2.], [3., 4.], [5., 6.]])
        y = np.array([1.0, 2.0, 3.0])
        nn = TestNN()
        nn.fit(X, y)
        assert hasattr(nn, '_y')
        assert nn._y.shape == (3,)

    def test_supervised_integer_mixin_fit(self):
        class TestNN(SupervisedIntegerMixin, NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                return self

        X = np.array([[1., 2.], [3., 4.], [5., 6.]])
        y = np.array([0, 1, 0])
        nn = TestNN()
        nn.fit(X, y)
        assert hasattr(nn, '_y')
        assert hasattr(nn, 'classes_')

    def test_supervised_integer_mixin_2d_y(self):
        class TestNN(SupervisedIntegerMixin, NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                return self

        X = np.array([[1., 2.], [3., 4.], [5., 6.]])
        y = np.array([[0, 1], [1, 0], [0, 0]])
        nn = TestNN()
        nn.fit(X, y)
        assert nn.outputs_2d_ == True
        assert len(nn.classes_) == 2

    def test_supervised_integer_mixin_column_vector_warning(self):
        class TestNN(SupervisedIntegerMixin, NeighborsBase):
            @pytest.mark.skip(reason="abstract method")
            def _fit(self, X):
                return self

        X = np.array([[1., 2.], [3., 4.], [5., 6.]])
        y = np.array([[0], [1], [0]])
        nn = TestNN()
        with pytest.warns(UserWarning, match="A column-vector y was passed"):
            nn.fit(X, y)


