class TestValidMetrics:
    """Tests for VALID_METRICS constants"""

    def test_valid_metrics_structure(self):
        assert 'ball_tree' in VALID_METRICS
        assert 'kd_tree' in VALID_METRICS
        assert 'brute' in VALID_METRICS

    def test_valid_metrics_sparse_structure(self):
        assert 'ball_tree' in VALID_METRICS_SPARSE
        assert 'kd_tree' in VALID_METRICS_SPARSE
        assert 'brute' in VALID_METRICS_SPARSE

    def test_brute_has_many_metrics(self):
        assert len(VALID_METRICS['brute']) > 10

    def test_ball_tree_has_fewer_metrics(self):
        assert len(VALID_METRICS['ball_tree']) < len(VALID_METRICS['brute'])

    def test_kd_tree_has_fewer_metrics(self):
        assert len(VALID_METRICS['kd_tree']) < len(VALID_METRICS['brute'])

    def test_brute_includes_pairwise_functions(self):
        pairwise_keys = list(PAIRWISE_DISTANCE_FUNCTIONS.keys())
        brute_metrics = VALID_METRICS['brute']
        for key in pairwise_keys:
            assert key in brute_metrics

    def test_brute_additional_metrics(self):
        additional_metrics = ['braycurtis', 'canberra', 'chebyshev', 'correlation',
                             'cosine', 'dice', 'hamming', 'jaccard', 'mahalanobis']
        for metric in additional_metrics:
            assert metric in VALID_METRICS['brute']


