import copy
from unittest import mock

from django.conf import settings
from django.test import TestCase, override_settings

from django.core.checks import Error
from django.core.checks.templates import (
    E001,
    E002,
    E003,
    check_for_template_tags_with_the_same_name,
    check_setting_app_dirs_loaders,
    check_string_if_invalid_is_string,
)


class CheckSettingAppDirsLoadersTests(TestCase):
    def test_no_error_when_app_dirs_false(self):
        with override_settings(TEMPLATES=[{"APP_DIRS": False}]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(errors, [])

    def test_no_error_when_loaders_not_specified(self):
        with override_settings(TEMPLATES=[{"APP_DIRS": True, "OPTIONS": {}}]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(errors, [])

    def test_error_when_both_app_dirs_and_loaders_specified(self):
        with override_settings(TEMPLATES=[{"APP_DIRS": True, "OPTIONS": {"loaders": []}}]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(len(errors), 1)
            self.assertEqual(errors[0], E001)

    def test_multiple_templates_one_with_error(self):
        with override_settings(TEMPLATES=[
            {"APP_DIRS": True, "OPTIONS": {}},
            {"APP_DIRS": True, "OPTIONS": {"loaders": []}},
        ]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(len(errors), 1)
            self.assertEqual(errors[0], E001)

    def test_multiple_templates_all_with_error(self):
        with override_settings(TEMPLATES=[
            {"APP_DIRS": True, "OPTIONS": {"loaders": []}},
            {"APP_DIRS": True, "OPTIONS": {"loaders": ["loader1"]}},
        ]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(len(errors), 1)
            self.assertEqual(errors[0], E001)

    def test_no_error_when_app_dirs_true_but_options_empty(self):
        with override_settings(TEMPLATES=[{"APP_DIRS": True, "OPTIONS": {}}]):
            errors = check_setting_app_dirs_loaders(None)
            self.assertEqual(errors, [])


class CheckStringIfInvalidIsStringTests(TestCase):
    def test_no_error_when_string_if_invalid_is_string(self):
        with override_settings(TEMPLATES=[{"OPTIONS": {"string_if_invalid": ""}}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(errors, [])

    def test_no_error_when_string_if_invalid_missing(self):
        with override_settings(TEMPLATES=[{"OPTIONS": {}}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(errors, [])

    def test_no_error_when_string_if_invalid_default(self):
        with override_settings(TEMPLATES=[{}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(errors, [])

    def test_error_when_string_if_invalid_is_integer(self):
        with override_settings(TEMPLATES=[{"OPTIONS": {"string_if_invalid": 123}}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(len(errors), 1)
            self.assertIn("must be a string", errors[0].msg)
            self.assertIn("int", errors[0].msg)

    def test_error_when_string_if_invalid_is_none(self):
        with override_settings(TEMPLATES=[{"OPTIONS": {"string_if_invalid": None}}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(len(errors), 1)
            self.assertIn("must be a string", errors[0].msg)
            self.assertIn("NoneType", errors[0].msg)

    def test_error_when_string_if_invalid_is_list(self):
        with override_settings(TEMPLATES=[{"OPTIONS": {"string_if_invalid": ["a", "b"]}}]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(len(errors), 1)
            self.assertIn("must be a string", errors[0].msg)
            self.assertIn("list", errors[0].msg)

    def test_multiple_templates_with_errors(self):
        with override_settings(TEMPLATES=[
            {"OPTIONS": {"string_if_invalid": 123}},
            {"OPTIONS": {"string_if_invalid": None}},
        ]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(len(errors), 2)

    def test_mixed_valid_and_invalid_templates(self):
        with override_settings(TEMPLATES=[
            {"OPTIONS": {"string_if_invalid": ""}},
            {"OPTIONS": {"string_if_invalid": 123}},
            {"OPTIONS": {}},
        ]):
            errors = check_string_if_invalid_is_string(None)
            self.assertEqual(len(errors), 1)


class CheckForTemplateTagsWithSameNameTests(TestCase):
    @mock.patch('django.core.checks.templates.get_template_tag_modules')
    def test_no_error_when_unique_module_names(self, mock_get_modules):
        mock_get_modules.return_value = [
            ("myapp.tags", "path/to/module1"),
            ("otherapp.tags", "path/to/module2"),
        ]
        with override_settings(TEMPLATES=[{"OPTIONS": {"libraries": {}}}]):
            errors = check_for_template_tags_with_the_same_name(None)
            self.assertEqual(errors, [])

    @mock.patch('django.core.checks.templates.get_template_tag_modules')
    def test_error_when_custom_library_conflicts_with_builtin(self, mock_get_modules):
        mock_get_modules.return_value = [
            ("custom_tags", "django.contrib.admin.templatetags.custom_tags"),
        ]
        with override_settings(TEMPLATES=[{
            "OPTIONS": {
                "libraries": {
                    "custom_tags": "myapp.templatetags.custom_tags",
                }
            }
        }]):
            errors = check_for_template_tags_with_the_same_name(None)
            self.assertEqual(len(errors), 1)
            self.assertIn("custom_tags", errors[0].msg)
            self.assertIn("templates.E003", errors[0].id)

    @mock.patch('django.core.checks.templates.get_template_tag_modules')
    def test_error_when_multiple_custom_libraries_same_name(self, mock_get_modules):
        mock_get_modules.return_value = []
        with override_settings(TEMPLATES=[{
            "OPTIONS": {
                "libraries": {
                    "tags": "myapp.templatetags.tags",
                }
            }
        }, {
            "OPTIONS": {
                "libraries": {
                    "tags": "otherapp.templatetags.tags",
                }
            }
        }]):
            errors = check_for_template_tags_with_the_same_name(None)
            self.assertEqual(len(errors), 1)
            self.assertIn("tags", errors[0].msg)
