class MediaTests(TestCase):
    def test_init_with_media(self):
        media = Media(css={'all': ['style.css']}, js=['script.js'])
        self.assertEqual(media._css_lists[0], {'all': ['style.css']})
        self.assertEqual(media._js_lists[0], ['script.js'])

    def test_init_with_none(self):
        media = Media()
        self.assertEqual(media._css_lists[0], {})
        self.assertEqual(media._js_lists[0], [])

    def test_merge_no_conflict(self):
        result = Media.merge(['a', 'b'], ['b', 'c'])
        self.assertEqual(result, ['a', 'b', 'c'])

    def test_merge_with_conflict(self):
        with self.assertWarns(MediaOrderConflictWarning):
            result = Media.merge(['a', 'b'], ['b', 'a'])
        self.assertEqual(result, ['a', 'b'])

    def test_render_js(self):
        media = Media(js=['test.js'])
        rendered = media.render_js()
        self.assertIn('test.js', str(rendered))

    def test_render_css(self):
        media = Media(css={'all': ['test.css']})
        rendered = media.render_css()
        self.assertIn('test.css', str(rendered))

    def test_absolute_path_relative(self):
        media = Media()
        with mock.patch('django.forms.widgets.static') as mock_static:
            mock_static.return_value = '/static/test.css'
            result = media.absolute_path('test.css')
            self.assertEqual(result, '/static/test.css')

    def test_absolute_path_absolute(self):
        media = Media()
        result = media.absolute_path('http://example.com/test.css')
        self.assertEqual(result, 'http://example.com/test.css')

    def test_absolute_path_root(self):
        media = Media()
        result = media.absolute_path('/test.css')
        self.assertEqual(result, '/test.css')

    def test_getitem_css(self):
        media = Media(css={'all': ['test.css']})
        css_media = media['css']
        self.assertIsInstance(css_media, Media)

    def test_getitem_js(self):
        media = Media(js=['test.js'])
        js_media = media['js']
        self.assertIsInstance(js_media, Media)

    def test_add_media(self):
        media1 = Media(css={'all': ['test1.css']})
        media2 = Media(css={'all': ['test2.css']})
        combined = media1 + media2
        self.assertEqual(len(combined._css_lists), 2)


