import pytest
import numpy as np
from matplotlib.figure import Figure
from mpl_toolkits.axes_grid1 import Grid, AxesGrid, ImageGrid
from mpl_toolkits.axes_grid1.axes_size import Size


class TestGrid:
    """Tests for the Grid class."""

    @pytest.fixture
    def fig(self):
        return Figure()

    @pytest.fixture
    def grid_basic(self, fig):
        return Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2))

    def test_grid_init_basic(self, fig):
        """Test basic Grid initialization."""
        grid = Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2))
        assert grid._nrows == 2
        assert grid._ncols == 2
        assert len(grid) == 4

    def test_grid_init_with_ngrids(self, fig):
        """Test Grid initialization with ngrids parameter."""
        grid = Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2), ngrids=3)
        assert len(grid) == 3

    def test_grid_init_invalid_ngrids(self, fig):
        """Test Grid initialization with invalid ngrids raises ValueError."""
        with pytest.raises(ValueError):
            Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2), ngrids=0)
        with pytest.raises(ValueError):
            Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2), ngrids=10)

    def test_grid_direction_row(self, fig):
        """Test Grid with row direction."""
        grid = Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2), direction="row")
        assert grid._direction == "row"
        assert len(grid) == 4

    def test_grid_direction_column(self, fig):
        """Test Grid with column direction."""
        grid = Grid(fig, rect=[0.1, 0.1, 0.8, 0.8], nrows_ncols=(2, 2), direction="column")
