class UrlQuoteTests(unittest.TestCase):
    def test_urlquote(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlquote('hello world')
            self.assertEqual(result, 'hello%20world')

    def test_urlquote_with_safe(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlquote('/path/to/resource', safe='/')
            self.assertEqual(result, '/path/to/resource')

    def test_urlquote_plus(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlquote_plus('hello world')
            self.assertEqual(result, 'hello+world')

    def test_urlquote_plus_with_safe(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlquote_plus('hello world', safe=' ')
            self.assertEqual(result, 'hello world')

    def test_urlunquote(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlunquote('hello%20world')
            self.assertEqual(result, 'hello world')

    def test_urlunquote_plus(self):
        with self.assertWarns(RemovedInDjango40Warning):
            result = urlunquote_plus('hello+world')
            self.assertEqual(result, 'hello world')


class UrlEncodeTests(unittest.TestCase):
    def test_urlencode_basic(self):
        result = urlencode({'key': 'value'})
        self.assertIn('key=value', result)

    def test_urlencode_multivaluedict(self):
        mvd = MultiValueDict({'key': ['value1', 'value2']})
        result = urlencode(mvd, doseq=True)
        self.assertIn('key=value1', result)
        self.assertIn('key=value2', result)

    def test_urlencode_none_value_raises(self):
        with self.assertRaises(TypeError):
            urlencode({'key': None})

    def test_urlencode_doseq_list(self):
        result = urlencode({'key': ['a', 'b']}, doseq=True)
        self.assertIn('key=a', result)
        self.assertIn('key=b', result)

    def test_urlencode_generator(self):
        def gen():
            yield 'a'
            yield 'b'
        result = urlencode({'key': gen()}, doseq=True)
        self.assertIn('key=a', result)
        self.assertIn('key=b', result)

    def test_urlencode_bytes_value(self):
        result = urlencode({'key': b'value'})
        self.assertIn('key=value', result)

    def test_urlencode_empty_string_value(self):
        result = urlencode({'key': ''})
        self.assertIn('key=', result)


