class HttpDateFormatTests(unittest.TestCase):
    def test_http_date_format_contains_gmt(self):
        result = http_date()
        self.assertIn('GMT', result)

    def test_http_date_format_weekday(self):
        result = http_date()
        weekday = result[:3]
        valid_weekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
        self.assertIn(weekday, valid_weekdays)

    def test_http_date_format_month(self):
        result = http_date()
        month = result.split()[2][:3]
        valid_months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
        self.assertIn(month, valid_months)

    def test_http_date_format_time(self):
        result = http_date()
        time_part = result.split()[4]
        parts = time_part.split(':')
        self.assertEqual(len(parts), 3)
        hour, minute, second = map(int, parts)
        self.assertLessEqual(hour, 23)
        self.assertLessEqual(minute, 59)
        self.assertLessEqual(second, 59)


