"""
Unit tests for sympy.core.function module.

Tests cover Function classes, Derivatives, Lambda, Subs, and related utilities.
"""

import pytest
from sympy import (
    Symbol, Function, Derivative, Lambda, Subs, diff, expand,
    sin, cos, exp, log, sqrt, pi, E, I, oo, zoo, nan, S,
    WildFunction, Dummy, Add, Mul, Pow, Rational, Float,
    MatrixSymbol, Integral, Sum, Order, tan, cot, sinh, cosh,
    tanh, coth, conjugate, re, im, arg, gamma, atan2, loggamma,
    symbols, simplify, factor_terms, signsimp,
    IndexedBase, Idx, Tuple, Dict, FiniteSet, Naturals0,
    BadSignatureError, BadArgumentsError, ArgumentIndexError, PoleError
)
from sympy.abc import x, y, z, t
from sympy.core.function import (
    FunctionClass, Application, Function, AppliedUndef, 
    UndefinedFunction, arity, _coeff_isneg, _derivative_dispatch
)


class TestFunctionCreation:
    """Test basic function creation and manipulation."""

    def test_undefined_function_creation(self):
        f = Function('f')
        assert f(x).func == f
        assert f(x).args == (x,)

    def test_undefined_function_with_nargs(self):
        f = Function('f', nargs=1)
        assert f(1).nargs == FiniteSet(1)

    def test_undefined_function_with_multiple_nargs(self):
        f = Function('f', nargs=(1, 2))
        assert f(1).nargs == FiniteSet(1, 2)
        assert f(1, 2).nargs == FiniteSet(1, 2)

    def test_function_assumptions(self):
        f_real = Function('f', real=True)
        assert f_real(x).is_real

    def test_function_from_symbol(self):
        f_sym = Function(Symbol('f', real=True))
        assert f_sym(x).is_real

    def test_function_class_key(self):
        from sympy import exp, log, sin, cos
        assert exp.class_key() == (4, 10, 'exp')
        assert sin.class_key() == (4, 20, 'sin')


class TestFunctionEvaluation:
    """Test function evaluation and simplification."""

    def test_eval_method(self):
        class my_func(Function):
            @classmethod
            def eval(cls, x):
                if x.is_Number:
                    if x.is_zero:
                        return S.One
                    elif x is S.Infinity:
                        return S.Zero
                return None

        assert my_func(0) == S.One
        assert my_func(oo) == S.Zero

    def test_function_diff_wrt(self):
        f = Function('f')
        assert not f(x)._diff_wrt

    def test_applied_undef_diff_wrt(self):
        f = Function('f')
        assert f(x)._diff_wrt


class TestDerivativeBasic:
    """Test basic derivative operations."""

    def test_simple_derivative(self):
        assert diff(x**2, x) == 2*x

    def test_multiple_derivative(self):
        assert diff(x**3, x, x) == 6*x

    def test_derivative_with_count(self):
        assert diff(x**3, x, 3) == 6

    def test_unevaluated_derivative(self):
        result = diff(sin(x), x, evaluate=False)
        assert isinstance(result, Derivative)

    def test_derivative_of_function(self):
        f = Function('f')
        result = diff(f(x), x)
        assert isinstance(result, Derivative)

    def test_derivative_chain_rule(self):
        f = Function('f')
        g = Function('g')
        result = diff(f(g(x)), x)
        assert result == Derivative(f(g(x)), g(x))*Derivative(g(x), x)

    def test_derivative_with_non_symbol(self):
        f = Function('f')
        # Should raise ValueError for non-differentiable variable
        with pytest.raises(ValueError):
            diff(x*y, x*y)

    def test_derivative_zero_result(self):
        f = Function('f')
        assert diff(f(y), x) == 0

    def test_derivative_canonical_ordering(self):
        f = Function('f')
        result = Derivative(f(x, y), y, x, evaluate=True)
        assert result == Derivative(f(x, y), x, y)


