class TestSubsOperations:
    """Test substitution operations."""

    def test_basic_subs(self):
        f = Function('f')
        s = Subs(f(x)*sin(y) + z, (x, y), (0, 1))
        result = s.doit()
        assert result == z + f(0)*sin(1)

    def test_subs_derivative(self):
        f = Function('f')
        s = Subs(Derivative(f(x), x), x, 0)
        result = s.subs(f, sin).doit()
        assert result == cos(0)

    def test_subs_self_mapping(self):
        s = Subs(x, x, 0)
        result = s.doit()
        assert result == 0

    def test_subs_evaluation(self):
        s = Subs(x, x, 0)
        assert s.evalf() == 0

    def test_subs_free_symbols(self):
        s = Subs(x + y, x, 0)
        assert y in s.free_symbols
        assert x not in s.free_symbols


class TestWildFunction:
    """Test WildFunction pattern matching."""

    def test_wildfunction_match(self):
        F = WildFunction('F')
        f = Function('f')

        assert F.match(F) == {F: F}
        assert f(x).match(F) == {F: f(x)}
        assert cos(x).match(F) == {F: cos(x)}

    def test_wildfunction_nargs(self):
        F = WildFunction('F', nargs=2)
        f = Function('f')

        assert f(x).match(F) is None
        assert f(x, y).match(F) == {F: f(x, y)}

    def test_wildfunction_range_nargs(self):
        F = WildFunction('F', nargs=(1, 2))
        f = Function('f')

        assert f(x).match(F) == {F: f(x)}
        assert f(x, y).match(F) == {F: f(x, y)}
        assert f(x, y, 1).match(F) is None


