class CapFirstTests(TestCase):
    def test_capfirst_basic(self):
        self.assertEqual(text.capfirst("hello"), "Hello")
        self.assertEqual(text.capfirst("HELLO"), "HELLO")
        self.assertEqual(text.capfirst(""), "")
        self.assertEqual(text.capfirst(None), None)

    def test_capfirst_with_numbers(self):
        self.assertEqual(text.capfirst("123abc"), "123abc")
        self.assertEqual(text.capfirst("a1b2c3"), "A1b2c3")


class WrapTests(TestCase):
    def test_wrap_basic(self):
        result = text.wrap("This is a test", 10)
        self.assertIn("\n", result)

    def test_wrap_preserves_linebreaks(self):
        text_with_breaks = "Line one\nLine two"
        result = text.wrap(text_with_breaks, 10)
        self.assertIn("\n", result)

    def test_wrap_no_wrap_needed(self):
        short_text = "Hi"
        result = text.wrap(short_text, 10)
        self.assertEqual(result, short_text)

    def test_wrap_long_words(self):
        long_word = "Supercalifragilisticexpialidocious"
        result = text.wrap(long_word, 10)
        # Long words shouldn't be wrapped
        self.assertNotIn("\n", result)


class TruncatorTests(TestCase):
    def setUp(self):
        self.truncator = text.Truncator("This is a test string")

    def test_chars_basic(self):
        result = self.truncator.chars(10)
        self.assertIn("…", result)
        self.assertLess(len(result), len("This is a test string"))

    def test_chars_no_truncate_needed(self):
        result = self.truncator.chars(100)
        self.assertEqual(result, "This is a test string")

    def test_chars_custom_truncate(self):
        result = self.truncator.chars(10, truncate="...")
        self.assertIn("...", result)

    def test_chars_html(self):
        html_text = "<p>This is <strong>bold</strong> text</p>"
        truncator = text.Truncator(html_text)
        result = truncator.chars(10, html=True)
        self.assertIsInstance(result, str)

    def test_words_basic(self):
        result = self.truncator.words(3)
        self.assertIn("…", result)
        word_count = len(result.split())
        self.assertLessEqual(word_count, 3 + 1)  # +1 for ellipsis

    def test_words_no_truncate_needed(self):
        result = self.truncator.words(100)
        self.assertEqual(result, "This is a test string")

    def test_words_custom_truncate(self):
