class CompressStringTests(TestCase):
    def test_compress_string(self):
        original = "Hello World"
        compressed = text.compress_string(original)
        self.assertIsNotNone(compressed)
        self.assertGreater(len(compressed), 0)

    def test_decompress_compressed_string(self):
        original = "Hello World"
        compressed = text.compress_string(original)
        zbuf = BytesIO(compressed)
        with GzipFile(fileobj=zbuf, mode='rb') as f:
            decompressed = f.read().decode('utf-8')
        self.assertEqual(decompressed, original)


